mapper.update:
UPDATE minio_object_outbox
SET status = 'IN_PROGRESS', lease_until = #{leaseUntil}, updated_at = #{now}
WHERE id = #{id}
  AND status = 'PENDING'

UPDATE minio_object_outbox
SET status = 'DONE', lease_until = NULL, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE minio_object_outbox
SET status = 'DEAD', last_error = #{lastError}, lease_until = NULL, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
